const CACHE='epa-v9';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./index.html','./style.css','./game.js','./advanced.js','./manifest.json','./terms.html','./privacy.html','./copyright.html','./install.html','./install.js','./language.js','./assets/app-192.png','./assets/app-512.png','./assets/apple-touch-icon.png','./assets/epa-logo.png','./assets/festival-welcome.webp','./assets/festival-evening.webp'])));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(new URL(e.request.url).origin!==self.location.origin||e.request.method!=='GET')return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
